import{_ as e,c as t,o,a2 as a}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"CoreController","description":"","frontmatter":{"sidebarPos":7,"sidebarTitle":"CoreController"},"headers":[],"relativePath":"system-reference/backend/http/controllers/core-controller.md","filePath":"system-reference/backend/http/controllers/core-controller.md","lastUpdated":1778363927000}'),r={name:"system-reference/backend/http/controllers/core-controller.md"},s=a('<h1 id="corecontroller" tabindex="-1">CoreController <a class="header-anchor" href="#corecontroller" aria-label="Permalink to &quot;CoreController&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Controllers/CoreController.php</code><br><strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Controllers</code><br><strong>Extends</strong>: <code>Controller</code><br><strong>Traits</strong>: <code>AuthorizesRequests</code>, <code>DispatchesJobs</code>, <code>ValidatesRequests</code>, <code>ManageNames</code>, <code>Moduleable</code>, <code>ManageModuleRoute</code>, <code>ManageTraits</code></p><p>Foundation for all Modularous panel and API controllers. On construction it discovers the current module from the file path, resolves the repository, and loads module configuration — so subclasses always have <code>$moduleName</code>, <code>$modelName</code>, <code>$config</code>, and <code>$repository</code> available.</p><h2 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h2><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> __construct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Application</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $app, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Request</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $request)</span></span></code></pre></div><ol><li>Stores <code>$app</code> and <code>$request</code>.</li><li>Calls trait hooks: <code>__beforeConstruct()</code> → <code>preload()</code> → <code>__afterConstruct()</code>.</li></ol><h3 id="hook-methods" tabindex="-1">Hook methods <a class="header-anchor" href="#hook-methods" aria-label="Permalink to &quot;Hook methods&quot;">​</a></h3><table><thead><tr><th>Method</th><th>Purpose</th></tr></thead><tbody><tr><td><code>__beforeConstruct(...$args)</code></td><td>Called before <code>preload()</code>. Traits may override this to run setup first.</td></tr><tr><td><code>__afterConstruct(...$args)</code></td><td>Called after <code>preload()</code>. Traits may override this to run setup last.</td></tr></tbody></table><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table><thead><tr><th>Property</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>$app</code></td><td><code>Application</code></td><td>Laravel service container</td></tr><tr><td><code>$baseKey</code></td><td><code>string</code></td><td>Module namespace key in snake_case</td></tr><tr><td><code>$request</code></td><td><code>Request</code></td><td>Current HTTP request</td></tr><tr><td><code>$namespace</code></td><td><code>string</code></td><td>Module PHP namespace</td></tr><tr><td><code>$moduleName</code></td><td><code>string</code></td><td>Discovered module name</td></tr><tr><td><code>$modelName</code></td><td><code>string</code></td><td>Model name (capitalised route name)</td></tr><tr><td><code>$config</code></td><td><code>object</code></td><td>Module configuration object</td></tr><tr><td><code>$repository</code></td><td><code>Repository|null</code></td><td>Model repository instance</td></tr></tbody></table><h2 id="module-discovery" tabindex="-1">Module Discovery <a class="header-anchor" href="#module-discovery" aria-label="Permalink to &quot;Module Discovery&quot;">​</a></h2><h3 id="getmodulename-string" tabindex="-1"><code>getModuleName(): ?string</code> <a class="header-anchor" href="#getmodulename-string" aria-label="Permalink to &quot;`getModuleName(): ?string`&quot;">​</a></h3><p>Discovers the module name by matching the controller&#39;s file path against the registered modules directories. Returns the first segment after the modules root, e.g. <code>app/Modules/Blog/...</code> → <code>Blog</code>.</p><h3 id="getnamespace-string" tabindex="-1"><code>getNamespace(): string</code> <a class="header-anchor" href="#getnamespace-string" aria-label="Permalink to &quot;`getNamespace(): string`&quot;">​</a></h3><p>Returns the PHP namespace for the current module (e.g. <code>Modules\\Blog</code>).</p><h3 id="preload-void" tabindex="-1"><code>preload(): void</code> <a class="header-anchor" href="#preload-void" aria-label="Permalink to &quot;`preload(): void`&quot;">​</a></h3><p>Loads <code>$moduleName</code>, <code>$modelName</code>, <code>$config</code>, <code>$routeName</code>, and <code>$repository</code>. Called automatically during construction.</p><h2 id="repository" tabindex="-1">Repository <a class="header-anchor" href="#repository" aria-label="Permalink to &quot;Repository&quot;">​</a></h2><h3 id="getrepository-repository" tabindex="-1"><code>getRepository(): ?Repository</code> <a class="header-anchor" href="#getrepository-repository" aria-label="Permalink to &quot;`getRepository(): ?Repository`&quot;">​</a></h3><p>Initialises and returns the model repository. Resolves by convention — looks for <code>{Module}\\Repositories\\{Model}Repository</code> in the container.</p><h3 id="getrepositoryclass-string-model-string" tabindex="-1"><code>getRepositoryClass(string $model): ?string</code> <a class="header-anchor" href="#getrepositoryclass-string-model-string" aria-label="Permalink to &quot;`getRepositoryClass(string $model): ?string`&quot;">​</a></h3><p>Finds the repository class for a given model name. Returns <code>null</code> if none is registered.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="getmoduleconfig-object" tabindex="-1"><code>getModuleConfig(): object</code> <a class="header-anchor" href="#getmoduleconfig-object" aria-label="Permalink to &quot;`getModuleConfig(): object`&quot;">​</a></h3><p>Returns the full configuration object for the current module route.</p><h3 id="getconfigfieldsbyroute-string-fieldname-default-null-mixed" tabindex="-1"><code>getConfigFieldsByRoute(string $fieldName, $default = null): mixed</code> <a class="header-anchor" href="#getconfigfieldsbyroute-string-fieldname-default-null-mixed" aria-label="Permalink to &quot;`getConfigFieldsByRoute(string $fieldName, $default = null): mixed`&quot;">​</a></h3><p>Gets a config field for the current route. Returns <code>$default</code> if absent.</p><h3 id="getconfigfieldsbyrouteraw-string-fieldname-default-null-mixed" tabindex="-1"><code>getConfigFieldsByRouteRaw(string $fieldName, $default = null): mixed</code> <a class="header-anchor" href="#getconfigfieldsbyrouteraw-string-fieldname-default-null-mixed" aria-label="Permalink to &quot;`getConfigFieldsByRouteRaw(string $fieldName, $default = null): mixed`&quot;">​</a></h3><p>Same as above but bypasses any transformation — returns raw config values.</p><h2 id="route-utilities" tabindex="-1">Route Utilities <a class="header-anchor" href="#route-utilities" aria-label="Permalink to &quot;Route Utilities&quot;">​</a></h2><h3 id="routeparameters-array" tabindex="-1"><code>routeParameters(): array</code> <a class="header-anchor" href="#routeparameters-array" aria-label="Permalink to &quot;`routeParameters(): array`&quot;">​</a></h3><p>Returns all parameters from the current route.</p><h3 id="routearguments-array" tabindex="-1"><code>routeArguments(): array</code> <a class="header-anchor" href="#routearguments-array" aria-label="Permalink to &quot;`routeArguments(): array`&quot;">​</a></h3><p>Returns route parameters merged with host-routing context (e.g. tenant ID).</p><h3 id="routemodulearguments-array" tabindex="-1"><code>routeModuleArguments(): array</code> <a class="header-anchor" href="#routemodulearguments-array" aria-label="Permalink to &quot;`routeModuleArguments(): array`&quot;">​</a></h3><p>Converts route argument keys to StudlyCase — useful when passing arguments to module-aware methods.</p><h3 id="routeargument-mixed" tabindex="-1"><code>routeArgument(): mixed</code> <a class="header-anchor" href="#routeargument-mixed" aria-label="Permalink to &quot;`routeArgument(): mixed`&quot;">​</a></h3><p>Returns the argument value for the current route (first parameter).</p><h3 id="parentroutearguments-array" tabindex="-1"><code>parentRouteArguments(): array</code> <a class="header-anchor" href="#parentroutearguments-array" aria-label="Permalink to &quot;`parentRouteArguments(): array`&quot;">​</a></h3><p>Returns only arguments that belong to parent routes (excludes current route parameter).</p><h3 id="routehastrait-string-behavior-bool" tabindex="-1"><code>routeHasTrait(string $behavior): bool</code> <a class="header-anchor" href="#routehastrait-string-behavior-bool" aria-label="Permalink to &quot;`routeHasTrait(string $behavior): bool`&quot;">​</a></h3><p>Returns <code>true</code> if the repository implements the given behaviour trait (e.g. <code>HasSoftDelete</code>, <code>HasRevisions</code>).</p><h3 id="routehas-string-behavior-bool" tabindex="-1"><code>routeHas(string $behavior): bool</code> <a class="header-anchor" href="#routehas-string-behavior-bool" aria-label="Permalink to &quot;`routeHas(string $behavior): bool`&quot;">​</a></h3><p>Alias for <code>routeHasTrait</code>.</p><h2 id="tag-assignment-endpoints" tabindex="-1">Tag &amp; Assignment Endpoints <a class="header-anchor" href="#tag-assignment-endpoints" aria-label="Permalink to &quot;Tag &amp; Assignment Endpoints&quot;">​</a></h2><p>These methods are called from generated module routes automatically.</p><h3 id="tags-jsonresponse" tabindex="-1"><code>tags(): JsonResponse</code> <a class="header-anchor" href="#tags-jsonresponse" aria-label="Permalink to &quot;`tags(): JsonResponse`&quot;">​</a></h3><p>Returns all available tags for the current model, used to populate tag input fields.</p><h3 id="tagsupdate-jsonresponse" tabindex="-1"><code>tagsUpdate(): JsonResponse</code> <a class="header-anchor" href="#tagsupdate-jsonresponse" aria-label="Permalink to &quot;`tagsUpdate(): JsonResponse`&quot;">​</a></h3><p>Creates a new tag and returns it. Called when a user types a new tag value in the UI.</p><h3 id="assignments-int-id-jsonresponse" tabindex="-1"><code>assignments(int $id): JsonResponse</code> <a class="header-anchor" href="#assignments-int-id-jsonresponse" aria-label="Permalink to &quot;`assignments(int $id): JsonResponse`&quot;">​</a></h3><p>Returns the current assignments for a model instance.</p><h3 id="createassignment-int-id-jsonresponse" tabindex="-1"><code>createAssignment(int $id): JsonResponse</code> <a class="header-anchor" href="#createassignment-int-id-jsonresponse" aria-label="Permalink to &quot;`createAssignment(int $id): JsonResponse`&quot;">​</a></h3><p>Creates or updates an assignment with status and optional file attachments.</p>',54),d=[s];function n(i,l,c,u,h,p){return o(),t("div",null,d)}const b=e(r,[["render",n]]);export{m as __pageData,b as default};
